import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import javax.imageio.ImageIO;
import org.jlinalg.plot.SignacCoveragePlot;
import org.jlinalg.sequence.*;
import org.yaml.snakeyaml.LoaderOptions;
import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.constructor.SafeConstructor;
import static org.jlinalg.cli.SeuratDifferentialContracts.*;
import static org.jlinalg.cli.SignacCoverageRequest.value;

/** Native standalone coverage/annotation plots with full numeric and deterministic SVG replay. */
public final class SignacCoverageCli {
    private SignacCoverageCli() { }
    static final String ENGINE="native-Signac-coverage-annotation-development";
    static final String SCOPE="DEVELOPMENT_SCOPE: native original Signac1.9/1.14/1.17 single-assay coverage endpoint/scaling/rolling/sampling and gene/transcript geometry, validated under the retained R4.6.1 dependency profile. The native SVG/PNG style is independent of ggplot pixel rendering. No expression, BigWig, tile, link, peak or multi-assay panel is inferred. Broader Signac/catalog/public integration, historical whole environments and biological/full-paper reproduction remain unfinished.";
    static final String ACTION="Read WARNINGS.md, analysis-status.json, diagnostics.json, group-scaling.tsv, complete group-cuts.tsv, sampled coverage.tsv and annotation tables before interpreting the figure. FAIL2 admits no result, including retained partial tables/images. Correct the named input, mapping, population, annotation, nonfinite/empty signal or capacity cause and retry into NEW output paths. Java arithmetic and SVG replay need no R or Signac installation. SKIP3 means the required full Java desktop/font/PNG runtime is unavailable or forbidden: skip dependent plotting, provide a permitted compatible JDK where allowed, then retry into NEW paths. Analysis never installs. Supply assay-wide nCount values; do not substitute region totals or read-support weights. VERIFY replays native arithmetic and SVG bytes and checks PNG dimensions, but does not rerender raster fonts, authenticate execution/biology or certify a paper.";
    public static void main(String[] args){System.exit(run(args,System.out,System.err));}
    static int run(String[] args,PrintStream out,PrintStream err){
        try{
            if(args.length==1&&args[0].equals("--help")){emit(out,"SignacCoverageCli --request UTF8_JSON\nModes: COVERAGE, VERIFY. All paths resolve against the request directory. Use NEW outputs.\n"+SCOPE+"\n"+ACTION);return 0;}
            if(args.length!=2||!args[0].equals("--request"))throw new IOException("Require --request UTF8_JSON or --help");Path path=Path.of(args[1]).toAbsolutePath().normalize();var raw=read(path);
            if("VERIFY".equals(raw.get("mode"))){keys(raw,Set.of("schema_version","mode","analysis"));if(integer(raw,"schema_version",0,1,1)!=1)throw new IOException("Require schema1");verify(resolve(path.getParent(),text(raw,"analysis")));emit(out,"Verified native coverage arithmetic, annotations and SVG geometry. "+ACTION);return 0;}
            var r=SignacCoverageRequest.validate(raw);byte[] original=Files.readAllBytes(path);String originalHash=SeuratDifferentialRuntime.sha(original);Path target=resolve(path.getParent(),text(r,"out"));int[] code={0};
            FollowupSupport.externalTransaction(Map.of("out",target.toString()),ENGINE,(stage,manifest)->{
                Map<String,Object> state=new LinkedHashMap<>();state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("results_admitted",false);List<String> warnings=new ArrayList<>(List.of(SCOPE));
                try{
                    if(!FollowupSupport.hash(path).equals(originalHash))throw new IOException("Original coverage request changed before capture");Files.write(stage.resolve("source-request.json"),original,StandardOpenOption.CREATE_NEW);var captured=SignacCoverageRequest.captured(raw);var inputs=SignacCoverageRequest.capture(raw,captured,path.getParent(),stage,value(r,"maximum_input_bytes"));json(stage.resolve("request.json"),captured);var effective=SignacCoverageRequest.validate(captured);json(stage.resolve("effective-request.json"),effective);sources(stage,false);
                    warnings.addAll(calculate(stage,effective,false));for(var e:inputs.entrySet())if(!FollowupSupport.hash(stage.resolve(e.getKey())).equals(e.getValue()))throw new IOException("Captured coverage input changed");sources(stage,true);capacity(stage,value(effective,"maximum_output_bytes"));
                    state.put("status","completed-with-warnings");state.put("results_admitted",true);manifest.put("source_request_sha256",originalHash);manifest.put("captured_input_sha256",inputs);
                    json(stage.resolve("COMPLETED.json"),Map.of("engine",ENGINE,"status","completed-native-coverage-annotation","results_admitted",true,"execution_authentication",false,"raster_font_replay",false));
                }catch(NoClassDefFoundError|UnsatisfiedLinkError failure){code[0]=3;state.put("status","SKIP3_DEPENDENT_PLOTTING_SKIPPED");state.put("error",failure.toString());warnings.add("SKIP3: Java desktop/font/PNG requirements unavailable or forbidden; dependent plotting skipped. "+failure);}
                catch(Exception failure){code[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("error",failure.toString());warnings.add("FAIL2: "+failure+". No retained partial numeric/image output is admitted.");}
                catch(OutOfMemoryError failure){code[0]=2;state.put("status","FAIL2_NO_RESULT_ADMITTED");state.put("error","Java heap exhausted");warnings.add("FAIL2: Java heap exhausted; choose justified explicit capacities and Java heap, then retry in NEW output paths.");}
                if(code[0]!=0){state.put("results_admitted",false);if(Files.exists(stage.resolve("COMPLETED.json")))json(stage.resolve("COMPLETED.json"),Map.of("status",state.get("status"),"results_admitted",false));}
                state.put("required_action",ACTION);json(stage.resolve("analysis-status.json"),state);Files.writeString(stage.resolve("WARNINGS.md"),warningText(state.get("status").toString(),warnings),StandardCharsets.UTF_8);
                manifest.put("engine",ENGINE);manifest.put("analysis_status",state.get("status"));manifest.put("results_admitted",state.get("results_admitted"));manifest.put("scope",SCOPE);manifest.put("native_arithmetic_replay",true);manifest.put("deterministic_SVG_replay",true);manifest.put("raster_font_replay",false);manifest.put("execution_authentication",false);manifest.put("historical_whole_environment",false);json(stage.resolve("manifest.json"),manifest);
            });SignacPeaksCli.seal(target);if(code[0]==0)try{verify(target);}catch(Exception failure){code[0]=2;reject(target,failure);}
            emit(code[0]==0?out:err,(code[0]==0?"Completed native coverage capture: ":code[0]==3?"SKIP3 — DEPENDENT PLOTTING SKIPPED: ":"FAIL2 — NO COVERAGE RESULT ADMITTED: ")+target);if(code[0]!=0)emit(err,"Cause: "+read(target.resolve("analysis-status.json")).get("error"));emit(err,"WARNINGS / REQUIRED ACTIONS: "+target.resolve("WARNINGS.md")+"\n"+ACTION);return code[0];
        }catch(OutOfMemoryError failure){emit(err,"FAIL2 — NO COVERAGE RESULT ADMITTED: Java heap exhausted. "+ACTION);return 2;}
        catch(Exception failure){emit(err,"FAIL2 — NO COVERAGE RESULT ADMITTED: "+failure+"\n"+ACTION);return 2;}
    }
    private static List<String> calculate(Path root,Map<String,Object> r,boolean compare)throws IOException{
        List<SignacCoverage.Cell> cells=new ArrayList<>();for(String[] f:SignacCoverageRequest.table(root.resolve(text(r,"cell_metadata")),"cell\tgroup\tn_count",3,(int)value(r,"maximum_cells")))cells.add(new SignacCoverage.Cell(f[0],f[1],Double.parseDouble(f[2])));
        if(cells.stream().map(SignacCoverage.Cell::group).distinct().count()>value(r,"maximum_groups"))throw new IOException("Complete group population exceeds maximum_groups");
        List<SignacFragments.Source> sources=new ArrayList<>();for(Object o:list(r.get("sources"),"sources")){var s=object(o,"source");List<SignacFragments.Cell> map=null;if(s.containsKey("map")){map=new ArrayList<>();for(String[] f:SignacCoverageRequest.table(root.resolve(text(s,"map")),"cell\tbarcode",2,(int)value(r,"maximum_cells")))map.add(new SignacFragments.Cell(f[0],f[1]));}sources.add(new SignacFragments.Source(root.resolve(text(s,"fragments")),map));}
        var levels=r.containsKey("group_levels")?strings(r.get("group_levels"),"group_levels",1,512):null;var scale=SignacCoverage.scaling(cells,levels,r.containsKey("scale_factor")?((Number)r.get("scale_factor")).doubleValue():null);
        var limits=new SignacFragments.Limits(1,(int)value(r,"maximum_cells"),0,value(r,"maximum_fragment_records"),value(r,"maximum_contributions"),value(r,"maximum_decoded_bytes"),4094,1);var region=SignacCoverageRequest.region(r);var cuts=SignacCoverage.cuts(sources,cells,region,value(r,"maximum_signal_values"),limits,()->Thread.currentThread().isInterrupted());long[][] counts=cuts.counts();var track=SignacCoverage.track(cuts.groups(),counts,region.start(),scale.byGroup(),scale.scaleFactor(),SignacCoverageRequest.options(r),()->Thread.currentThread().isInterrupted());if(levels!=null)track=new SignacCoverage.Result(levels.stream().filter(cuts.groups()::contains).toList(),track.points(),track.ymax(),track.warnings());
        List<SignacCoverageAnnotations.Annotation> annotation=new ArrayList<>();if(r.containsKey("annotation"))for(String[] f:SignacCoverageRequest.table(root.resolve(text(r,"annotation")),"chromosome\tstart\tend\tstrand\tgene_name\ttx_id\tgene_biotype\ttype",8,(int)value(r,"maximum_annotations")))annotation.add(new SignacCoverageAnnotations.Annotation(f[0],Integer.parseInt(f[1]),Integer.parseInt(f[2]),f[3],f[4],f[5],f[6],f[7]));
        var layout=SignacCoverageAnnotations.layout(annotation,region,!r.get("annotation_mode").equals("transcript"),(int)value(r,"maximum_annotations"),(int)value(r,"maximum_segments"),()->Thread.currentThread().isInterrupted());
        Budget budget=new Budget(root,value(r,"maximum_output_bytes"),compare);
        try(var t=new Table(root.resolve("group-cuts.tsv"),compare,budget)){t.row("group","position","cut_count");for(int g=0;g<cuts.groups().size();g++)for(int p=0;p<counts[g].length;p++)t.row(cuts.groups().get(g),Integer.toString(region.start()+p),Long.toString(counts[g][p]));}
        try(var t=new Table(root.resolve("coverage.tsv"),compare,budget)){t.row("group","position","cut_count","normalized","coverage");for(var p:track.points())t.row(p.group(),Integer.toString(p.position()),Long.toString(p.count()),number(p.normalized()),number(p.coverage()));}
        try(var t=new Table(root.resolve("group-scaling.tsv"),compare,budget)){t.row("group","source_NA_slot","cells","scale_factor","global_scale_factor");for(int i=0;i<scale.names().size();i++)t.row(i==scale.names().size()-1?"":scale.names().get(i),Boolean.toString(i==scale.names().size()-1),scale.cellCounts().get(i).toString(),number(scale.factors().get(i)),number(scale.scaleFactor()));}
        try(var t=new Table(root.resolve("annotation-labels.tsv"),compare,budget)){t.row("chromosome","start","end","strand","gene_name","tx_id","gene_biotype","dodge","width","position");for(var p:layout.labels()){var b=p.body();t.row(b.chromosome(),number(b.start()),number(b.end()),b.strand(),b.geneName(),b.transcriptId(),b.biotype(),Integer.toString(b.dodge()),number(p.width()),number(p.position()));}}
        for(var entry:Map.of("annotation-exons.tsv",layout.exons(),"annotation-plus.tsv",layout.plus(),"annotation-minus.tsv",layout.minus()).entrySet())try(var t=new Table(root.resolve(entry.getKey()),compare,budget)){t.row("chromosome","start","end","strand","gene_name","tx_id","gene_biotype","type","dodge");for(var p:entry.getValue())t.row(p.chromosome(),number(p.start()),number(p.end()),p.strand(),p.geneName(),p.transcriptId(),p.biotype(),p.type(),Integer.toString(p.dodge()));}
        var images=SignacCoveragePlot.render(track,layout,region,text(r,"title"),(int)value(r,"plot_width"),(int)value(r,"maximum_plot_height"),r.get("annotation_mode").equals("transcript"),!compare);budget.bytes("coverage.svg",images.svg());
        if(compare){try(var in=ImageIO.createImageInputStream(root.resolve("coverage.png").toFile())){if(in==null)throw new IOException("PNG preview unavailable");var readers=ImageIO.getImageReaders(in);if(!readers.hasNext())throw new IOException("Invalid PNG preview");var reader=readers.next();try{reader.setInput(in);if(!reader.getFormatName().equalsIgnoreCase("png")||reader.getWidth(0)!=images.width()||reader.getHeight(0)!=images.height())throw new IOException("Raster format/dimensions differ from native scene");}finally{reader.dispose();}}}
        else budget.bytes("coverage.png",images.png());
        List<String> warnings=new ArrayList<>();warnings.addAll(scale.warnings());warnings.addAll(cuts.warnings());warnings.addAll(track.warnings());warnings.addAll(layout.warnings());warnings.add("NATIVE_RENDERING_SCOPE: deterministic SVG geometry replays exactly. PNG is a native Java2D preview with platform fonts; VERIFY checks format/dimensions but does not independently rerender its pixels. Neither image is a ggplot pixel replica. All requested groups/models remain present; unplottable source signals/limits fail instead of being silently fixed.");
        Map<String,Object> diagnostic=new LinkedHashMap<>();diagnostic.put("object_cells",cells.size());diagnostic.put("groups",cuts.groups());diagnostic.put("sampled_positions",track.points().size());diagnostic.put("source_ymax",number(track.ymax()));diagnostic.put("global_scale_factor",number(scale.scaleFactor()));diagnostic.put("annotation_labels",layout.labels().size());diagnostic.put("plot_width",images.width());diagnostic.put("plot_height",images.height());diagnostic.put("complete_scans",cuts.scans().stream().map(s->Map.of("records",s.records(),"decoded_bytes",s.decodedBytes(),"compressed",s.compressed(),"chromosomes",s.chromosomes())).toList());diagnostic.put("warnings",warnings);diagnostic.put("native_arithmetic_replay",true);diagnostic.put("SVG_replay",true);diagnostic.put("raster_font_replay",false);diagnostic.put("execution_authentication",false);
        if(compare){if(!same(diagnostic,read(root.resolve("diagnostics.json"),64000000)))throw new IOException("Native coverage diagnostic/scientific scope differs");}else json(root.resolve("diagnostics.json"),diagnostic);return warnings;
    }
    static void verify(Path root)throws IOException{
        root=root.toAbsolutePath().normalize();var seal=read(root.resolve("capture-files.json"),16000000);keys(seal,Set.of("schema_version","authentication","files","directories"));if(integer(seal,"schema_version",0,1,1)!=1||!Boolean.FALSE.equals(seal.get("authentication")))throw new IOException("Invalid native coverage seal");var actual=SeuratDifferentialRuntime.footprint(root);actual.remove("capture-files.json");var pins=object(seal.get("files"),"capture file hashes");if(!actual.keySet().equals(pins.keySet()))throw new IOException("Coverage complete file population differs");for(var e:pins.entrySet())if(!FollowupSupport.hash(root.resolve(e.getKey())).equals(e.getValue()))throw new IOException("Coverage capture hash mismatch: "+e.getKey());
        var state=read(root.resolve("analysis-status.json"));var manifest=read(root.resolve("manifest.json"));if(!"completed-with-warnings".equals(state.get("status"))||!Boolean.TRUE.equals(state.get("results_admitted"))||!ENGINE.equals(manifest.get("engine"))||!state.get("status").equals(manifest.get("analysis_status"))||!Boolean.TRUE.equals(manifest.get("results_admitted"))||!SCOPE.equals(manifest.get("scope"))||!ACTION.equals(state.get("required_action")))throw new IOException("Failed/skipped/unsupported coverage capture is not an admitted result");
        for(String k:List.of("raster_font_replay","execution_authentication","historical_whole_environment"))if(!Boolean.FALSE.equals(manifest.get(k)))throw new IOException("Unsupported coverage authentication/replay claim");for(String k:List.of("native_arithmetic_replay","deterministic_SVG_replay"))if(!Boolean.TRUE.equals(manifest.get(k)))throw new IOException("Missing native coverage replay contract");
        var original=read(root.resolve("source-request.json"));SignacCoverageRequest.validate(original);if(!FollowupSupport.hash(root.resolve("source-request.json")).equals(manifest.get("source_request_sha256")))throw new IOException("Original request hash differs");var request=read(root.resolve("request.json"));if(!same(SignacCoverageRequest.captured(original),request))throw new IOException("Captured request settings/population differ");var r=SignacCoverageRequest.validate(request);if(!same(r,read(root.resolve("effective-request.json"))))throw new IOException("Effective coverage settings differ");
        Set<String> expected=inputNames(r);var inputs=object(manifest.get("captured_input_sha256"),"captured input hashes");if(!expected.equals(inputs.keySet()))throw new IOException("Complete coverage input population differs");for(String n:expected)if(!FollowupSupport.hash(root.resolve(n)).equals(inputs.get(n)))throw new IOException("Captured input binding differs");sources(root,true);capacity(root,value(r,"maximum_output_bytes"));
        var warnings=new ArrayList<>(List.of(SCOPE));warnings.addAll(calculate(root,r,true));if(!Files.readString(root.resolve("WARNINGS.md"),StandardCharsets.UTF_8).equals(warningText("completed-with-warnings",warnings)))throw new IOException("Required coverage warning text differs");
        var completed=read(root.resolve("COMPLETED.json"));if(!ENGINE.equals(completed.get("engine"))||!"completed-native-coverage-annotation".equals(completed.get("status"))||!Boolean.TRUE.equals(completed.get("results_admitted"))||!Boolean.FALSE.equals(completed.get("execution_authentication"))||!Boolean.FALSE.equals(completed.get("raster_font_replay")))throw new IOException("Unsupported coverage completion claim");
        expected.addAll(List.of("source-request.json","request.json","effective-request.json","analysis-status.json","manifest.json","manifest.yaml","COMPLETED.json","capture-files.json","WARNINGS.md","diagnostics.json","group-cuts.tsv","coverage.tsv","group-scaling.tsv","annotation-labels.tsv","annotation-exons.tsv","annotation-plus.tsv","annotation-minus.tsv","coverage.svg","coverage.png","source/SOURCE-PROFILES.json"));for(String name:object(profile().get("files"),"profile files").keySet())expected.add("source/"+name);
        var withSeal=new HashSet<>(actual.keySet());withSeal.add("capture-files.json");if(!expected.equals(withSeal))throw new IOException("Unexpected/missing native coverage capture member");List<String> dirs;try(var paths=Files.walk(root)){Path base=root;dirs=paths.filter(p->!p.equals(base)&&Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS)).map(p->base.relativize(p).toString().replace('\\','/')).sorted().toList();}if(!dirs.equals(List.of("inputs","source"))||!dirs.equals(strings(seal.get("directories"),"directories",1,100)))throw new IOException("Unexpected coverage capture directories");
        LoaderOptions options=new LoaderOptions();options.setAllowDuplicateKeys(false);options.setMaxAliasesForCollections(0);options.setCodePointLimit(16000000);if(Files.size(root.resolve("manifest.yaml"))>16000000)throw new IOException("Generic coverage manifest exceeds capacity");Map<String,Object> yaml;try(var in=Files.newBufferedReader(root.resolve("manifest.yaml"),StandardCharsets.UTF_8)){yaml=object(new Yaml(new SafeConstructor(options)).load(in),"generic transaction manifest");}for(var e:manifest.entrySet())if(!same(e.getValue(),yaml.get(e.getKey())))throw new IOException("Generic/native coverage manifest binding differs");var outputPins=new TreeMap<String,Object>(pins);outputPins.remove("manifest.yaml");var genericPins=new TreeMap<String,Object>();for(var e:object(yaml.get("output_sha256"),"generic transaction hashes").entrySet())if(genericPins.put(e.getKey().replace('\\','/'),e.getValue())!=null)throw new IOException("Ambiguous generic output path transport");if(!same(outputPins,genericPins))throw new IOException("Generic transaction output hash/population differs");
    }
    private static Set<String> inputNames(Map<String,Object> r)throws IOException{Set<String> names=new HashSet<>(List.of(text(r,"cell_metadata")));if(r.containsKey("annotation"))names.add(text(r,"annotation"));for(Object o:list(r.get("sources"),"sources")){var s=object(o,"source");names.add(text(s,"fragments"));if(s.containsKey("map"))names.add(text(s,"map"));}return names;}
    private static byte[] resource(String name)throws IOException{try(var in=SignacCoverageCli.class.getResourceAsStream("/org/jlinalg/omics/signac-coverage/"+name)){if(in==null)throw new IOException("Missing packaged native coverage source: "+name);return in.readAllBytes();}}
    private static Map<String,Object> profile()throws IOException{return object(SimpleJson.parse(new String(resource("SOURCE-PROFILES.json"),StandardCharsets.UTF_8)),"coverage source profile");}
    private static void sources(Path root,boolean compare)throws IOException{Map<String,Object> files=new LinkedHashMap<>(object(profile().get("files"),"profile files"));files.put("SOURCE-PROFILES.json",Map.of("sha256",SeuratDifferentialRuntime.sha(resource("SOURCE-PROFILES.json"))));for(var e:files.entrySet()){if(!e.getKey().matches("[A-Za-z0-9._-]+"))throw new IOException("Unsafe coverage source name");byte[] bytes=resource(e.getKey());if(!SeuratDifferentialRuntime.sha(bytes).equals(object(e.getValue(),"source pin").get("sha256")))throw new IOException("Packaged coverage source changed");Path file=root.resolve("source/"+e.getKey());if(compare){if(!Arrays.equals(bytes,Files.readAllBytes(file)))throw new IOException("Captured coverage source changed");}else{Files.createDirectories(file.getParent());Files.write(file,bytes,StandardOpenOption.CREATE_NEW);}}}
    private static long capacity(Path root,long max)throws IOException{long sum=0;for(long n:SeuratDifferentialRuntime.footprint(root).values()){if(n>max-sum)throw new IOException("Complete capture byte capacity exceeded");sum+=n;}return sum;}
    private static String number(double n){return Double.isNaN(n)?"NaN":n==Double.POSITIVE_INFINITY?"Inf":n==Double.NEGATIVE_INFINITY?"-Inf":Double.toString(n);}
    private static String warningText(String state,List<String>warnings){return "# NATIVE COVERAGE: "+state+"\n\n"+String.join("\n\n",warnings)+"\n\nRequired action: "+ACTION+"\n";}
    private static void reject(Path root,Exception failure)throws IOException{var state=read(root.resolve("analysis-status.json"));state.put("status","FAIL2_PUBLISHED_VERIFICATION_FAILED");state.put("results_admitted",false);state.put("error",failure.toString());json(root.resolve("analysis-status.json"),state);var manifest=read(root.resolve("manifest.json"));manifest.put("analysis_status",state.get("status"));manifest.put("results_admitted",false);json(root.resolve("manifest.json"),manifest);json(root.resolve("COMPLETED.json"),Map.of("status",state.get("status"),"results_admitted",false));Files.writeString(root.resolve("WARNINGS.md"),"# FAIL2 — NO COVERAGE RESULT ADMITTED\n\n"+failure+"\n\nRequired action: "+ACTION+"\n\n"+Files.readString(root.resolve("WARNINGS.md")));SignacPeaksCli.seal(root);}
    private static void emit(PrintStream stream,String text){stream.writeBytes((text+"\n").getBytes(StandardCharsets.UTF_8));}
    private static final class Budget {final Path root;final long maximum;final boolean compare;long used;Budget(Path root,long maximum,boolean compare)throws IOException{this.root=root;this.maximum=maximum;this.compare=compare;used=capacity(root,maximum);}void add(long n)throws IOException{if(n>maximum-used)throw new IOException("Complete native output byte capacity exceeded");used+=n;}void bytes(String name,byte[] bytes)throws IOException{if(compare){if(!Arrays.equals(bytes,Files.readAllBytes(root.resolve(name))))throw new IOException("Native SVG geometry differs from replay");}else{add(bytes.length);Files.write(root.resolve(name),bytes,StandardOpenOption.CREATE_NEW);}}}
    private static final class Table implements AutoCloseable {final BufferedReader input;final OutputStream output;final Budget budget;Table(Path path,boolean compare,Budget budget)throws IOException{this.budget=budget;input=compare?SeuratDifferentialInputs.reader(path):null;output=compare?null:new BufferedOutputStream(Files.newOutputStream(path,StandardOpenOption.CREATE_NEW));}void row(String... values)throws IOException{SignacCoverageRequest.check();var text=new StringWriter();FollowupSupport.row(text,values);String line=text.toString();if(input!=null){if(!line.substring(0,line.length()-1).equals(SeuratDifferentialInputs.line(input)))throw new IOException("Native coverage table differs from input arithmetic/geometry");}else{byte[] bytes=line.getBytes(StandardCharsets.UTF_8);budget.add(bytes.length);output.write(bytes);}}public void close()throws IOException{if(input!=null)try{if(SeuratDifferentialInputs.line(input)!=null)throw new IOException("Extra native coverage rows");}finally{input.close();}else output.close();}}
}
